 13→#define NC_CHECK(call)                                                  \
 14→  do {                                                                  \
 15→    int nc_status_ = (call);                                            \
 16→    if (nc_status_ != NC_NOERR) {                                      \
 17→      throw IOError(std::string("NetCDF error: ") + nc_strerror(nc_status_)); \
 18→    }                                                                   \
 19→  } while (0)
