 21→namespace miem {
 22→
 23→CESReader::CESReader(CESReader&& other) noexcept
 24→    : ncid_(other.ncid_),
 25→      file_path_(std::move(other.file_path_)),
 26→      descriptor_(std::move(other.descriptor_)),
 27→      is_ces_compliant_(other.is_ces_compliant_),
 28→      n_time_steps_(other.n_time_steps_),
 29→      n_cells_(other.n_cells_),
 30→      available_species_(std::move(other.available_species_)) {
 31→  other.ncid_ = -1;
 32→}
 33→
 34→CESReader& CESReader::operator=(CESReader&& other) noexcept {
 35→  if (this != &other) {
 36→    Close();
 37→    ncid_ = other.ncid_;
 38→    file_path_ = std::move(other.file_path_);
 39→    descriptor_ = std::move(other.descriptor_);
 40→    is_ces_compliant_ = other.is_ces_compliant_;
 41→    n_time_steps_ = other.n_time_steps_;
 42→    n_cells_ = other.n_cells_;
 43→    available_species_ = std::move(other.available_species_);
 44→    other.ncid_ = -1;
 45→  }
 46→  return *this;
 47→}
 48→
 49→void CESReader::Open(const std::string& file_path,
 50→                     const DatasetDescriptor& descriptor) {
 51→  if (ncid_ >= 0) {
 52→    Close();
 53→  }
 54→
 55→  file_path_ = file_path;
 56→  descriptor_ = descriptor;
 57→
 58→  int status = nc_open(file_path.c_str(), NC_NOWRITE, &ncid_);
 59→  if (status != NC_NOERR) {
 60→    throw IOError("Failed to open NetCDF file: " + file_path +
 61→                  " — " + nc_strerror(status));
 62→  }
 63→
 64→  DetectFormat();
 65→  DiscoverSpecies();
 66→}
 67→
 68→void CESReader::Close() {
 69→  if (ncid_ >= 0) {
 70→    nc_close(ncid_);
 71→    ncid_ = -1;
 72→  }
 73→  available_species_.clear();
 74→  n_time_steps_ = 0;
 75→  n_cells_ = 0;
 76→}
 77→
 78→void CESReader::DetectFormat() {
 79→  // Check for CES compliance via global attribute
 80→  size_t att_len = 0;
 81→  int status = nc_inq_attlen(ncid_, NC_GLOBAL, "miem_version", &att_len);
 82→  is_ces_compliant_ = false;
 83→  if (status == NC_NOERR && att_len < 256) {
 84→    std::vector<char> version_buf(att_len + 1, '\0');
 85→    status = nc_get_att_text(ncid_, NC_GLOBAL, "miem_version", version_buf.data());
 86→    is_ces_compliant_ = (status == NC_NOERR);
 87→  }
 88→
 89→  // Get time dimension
 90→  int time_dim_id;
 91→  const std::string& time_dim_name =
 92→      is_ces_compliant_ ? "Time" : descriptor_.time_dimension;
 93→  status = nc_inq_dimid(ncid_, time_dim_name.c_str(), &time_dim_id);
 94→  if (status == NC_NOERR) {
 95→    size_t time_len;
 96→    NC_CHECK(nc_inq_dimlen(ncid_, time_dim_id, &time_len));
 97→    n_time_steps_ = static_cast<int>(time_len);
 98→  } else {
 99→    n_time_steps_ = 1;  // No time dimension; treat as single snapshot
100→  }
101→
102→  // Get cell dimension
103→  int cell_dim_id;
104→  const std::string& cell_dim_name =
105→      is_ces_compliant_ ? "nCells" : descriptor_.cell_dimension;
106→  status = nc_inq_dimid(ncid_, cell_dim_name.c_str(), &cell_dim_id);
107→  if (status != NC_NOERR) {
108→    throw IOError("Cannot find cell dimension '" + cell_dim_name +
109→                  "' in file: " + file_path_);
110→  }
111→  size_t cell_len;
112→  NC_CHECK(nc_inq_dimlen(ncid_, cell_dim_id, &cell_len));
113→  n_cells_ = static_cast<int>(cell_len);
114→}
115→
116→void CESReader::DiscoverSpecies() {
117→  available_species_.clear();
118→
119→  int n_vars;
120→  NC_CHECK(nc_inq_nvars(ncid_, &n_vars));
121→
122→  const std::string& prefix =
123→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
124→
125→  for (int varid = 0; varid < n_vars; ++varid) {
126→    char var_name[NC_MAX_NAME + 1];
127→    NC_CHECK(nc_inq_varname(ncid_, varid, var_name));
128→
129→    std::string name(var_name);
130→    if (name.substr(0, prefix.size()) == prefix) {
131→      std::string species = CanonicalName(name);
132→      available_species_.push_back(species);
133→    }
134→  }
135→}
136→
137→std::string CESReader::CanonicalName(const std::string& var_name) const {
138→  // Check descriptor rename map first
139→  auto it = descriptor_.species_rename.find(var_name);
140→  if (it != descriptor_.species_rename.end()) {
141→    // The rename target should be in emi_X format; strip prefix
142→    const std::string& renamed = it->second;
143→    if (renamed.substr(0, 4) == "emi_") {
144→      return renamed.substr(4);
145→    }
146→    return renamed;
147→  }
148→
149→  // Strip the variable prefix to get species name
150→  const std::string& prefix =
151→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
152→  if (var_name.substr(0, prefix.size()) == prefix) {
153→    return var_name.substr(prefix.size());
154→  }
155→  return var_name;
156→}
157→
158→std::vector<std::string> CESReader::QuerySpecies() const {
159→  return available_species_;
160→}
