 public:
  explicit SpeciesError(const std::string& message)
      : MIEMError("Species", message) {}
};

class ValidationError : public MIEMError {
 public:
  explicit ValidationError(const std::string& message)
      : MIEMError("Validation", message) {}
};

}  // namespace miem

