 35→CESReader& CESReader::operator=(CESReader&& other) noexcept {
 36→  if (this != &other) {
 37→    Close();
 38→    ncid_ = other.ncid_;
 39→    file_path_ = std::move(other.file_path_);
 40→    descriptor_ = std::move(other.descriptor_);
 41→    is_ces_compliant_ = other.is_ces_compliant_;
 42→    ses_version_ = std::move(other.ses_version_);
 43→    n_time_steps_ = other.n_time_steps_;
 44→    n_cells_ = other.n_cells_;
 45→    available_species_ = std::move(other.available_species_);
 46→    other.ncid_ = -1;
 47→  }
 48→  return *this;
 49→}
 50→
 51→void CESReader::Open(const std::string& file_path,
 52→                     const DatasetDescriptor& descriptor) {
 53→  if (ncid_ >= 0) {
 54→    Close();
 55→  }
 56→
 57→  file_path_ = file_path;
 58→  descriptor_ = descriptor;
 59→
 60→  int status = nc_open(file_path.c_str(), NC_NOWRITE, &ncid_);
 61→  if (status != NC_NOERR) {
 62→    throw IOError("Failed to open NetCDF file: " + file_path +
 63→                  " — " + nc_strerror(status));
 64→  }
 65→
 66→  DetectFormat();
 67→  DiscoverSpecies();
 68→}
 69→
 70→void CESReader::Close() {
 71→  if (ncid_ >= 0) {
 72→    nc_close(ncid_);
 73→    ncid_ = -1;
 74→  }
 75→  available_species_.clear();
 76→  n_time_steps_ = 0;
 77→  n_cells_ = 0;
 78→}
 79→
 80→void CESReader::DetectFormat() {
 81→  // Check for SES compliance first (ses_version), then fall back to
 82→  // legacy miem_version for backward compatibility.
 83→  is_ces_compliant_ = false;
 84→  ses_version_.clear();
 85→
 86→  auto try_read_attr = [&](const char* attr_name) -> bool {
 87→    size_t att_len = 0;
 88→    int status = nc_inq_attlen(ncid_, NC_GLOBAL, attr_name, &att_len);
 89→    if (status == NC_NOERR && att_len < 256) {
 90→      std::vector<char> buf(att_len + 1, '\0');
 91→      status = nc_get_att_text(ncid_, NC_GLOBAL, attr_name, buf.data());
 92→      if (status == NC_NOERR) {
 93→        ses_version_ = std::string(buf.data(), att_len);
 94→        is_ces_compliant_ = true;
 95→        return true;
 96→      }
 97→    }
 98→    return false;
 99→  };
100→
101→  // Prefer ses_version, fall back to miem_version
102→  if (!try_read_attr("ses_version")) {
103→    try_read_attr("miem_version");
104→  }
105→
106→  // Resolve time dimension: try SES names first, then legacy names
107→  int time_dim_id;
108→  int status;
109→  std::string time_dim_name;
110→
111→  if (is_ces_compliant_) {
112→    // SES 1.0 uses "time"; legacy CES used "Time"
113→    status = nc_inq_dimid(ncid_, "time", &time_dim_id);
114→    if (status == NC_NOERR) {
115→      time_dim_name = "time";
116→    } else {
117→      status = nc_inq_dimid(ncid_, "Time", &time_dim_id);
118→      time_dim_name = "Time";
119→    }
120→  } else {
121→    time_dim_name = descriptor_.time_dimension;
122→    status = nc_inq_dimid(ncid_, time_dim_name.c_str(), &time_dim_id);
123→  }
124→
125→  if (status == NC_NOERR) {
126→    size_t time_len;
127→    NC_CHECK(nc_inq_dimlen(ncid_, time_dim_id, &time_len));
128→    n_time_steps_ = static_cast<int>(time_len);
129→  } else {
130→    n_time_steps_ = 1;  // No time dimension; treat as single snapshot
131→  }
132→
133→  // Resolve cell dimension: try SES names first, then legacy names
134→  int cell_dim_id;
135→  std::string cell_dim_name;
136→
137→  if (is_ces_compliant_) {
138→    // SES 1.0 uses "n_cells"; legacy CES used "nCells"
139→    status = nc_inq_dimid(ncid_, "n_cells", &cell_dim_id);
140→    if (status == NC_NOERR) {
141→      cell_dim_name = "n_cells";
142→    } else {
143→      status = nc_inq_dimid(ncid_, "nCells", &cell_dim_id);
144→      cell_dim_name = "nCells";
