#pragma once

#include <string>
#include <vector>

#include "miem/dataset_descriptor.hpp"
#include "miem/util/types.hpp"

namespace miem {

// Reads SES (Standardized Emissions Schema) compliant NetCDF files,
// or non-standard files adapted through a DatasetDescriptor.
// Also accepts legacy CES files (miem_version, nCells, Time) for
// backward compatibility.
class SESReader {
 public:
  SESReader() = default;
  ~SESReader() { Close(); }

  // Non-copyable (owns a NetCDF file handle)
  SESReader(const SESReader&) = delete;
  SESReader& operator=(const SESReader&) = delete;
  SESReader(SESReader&& other) noexcept;
  SESReader& operator=(SESReader&& other) noexcept;

  // Open a NetCDF file. If descriptor is provided, use it for non-SES files.
  // If the file is SES-compliant, descriptor overrides are ignored.
  void Open(const std::string& file_path,
            const DatasetDescriptor& descriptor = DatasetDescriptor::Default());

  void Close();

  // Discover available species in the file
  std::vector<std::string> QuerySpecies() const;

  // Get the number of time steps in the file
  int NumTimeSteps() const { return n_time_steps_; }

  // Get time values (in seconds since reference, or as stored)
  std::vector<double> GetTimeValues() const;

  // Read flux data for all species at a given time index.
  // Returns data as (n_species * n_cells) array in kg/m^2/s.
  void ReadFlux(int time_index,
                const std::vector<std::string>& species_names,
                std::vector<Real>& flux_out,
                int& n_cells_out) const;

  bool IsOpen() const { return ncid_ >= 0; }

  int NumCells() const { return n_cells_; }

 private:
  int ncid_ = -1;
  std::string file_path_;
  DatasetDescriptor descriptor_;
  bool is_ses_compliant_ = false;
  std::string ses_version_;   // Detected SES/MIEM version string
  int n_time_steps_ = 0;
  int n_cells_ = 0;
  std::vector<std::string> available_species_;

  void DetectFormat();
  void DiscoverSpecies();
  std::string CanonicalName(const std::string& var_name) const;
};

}  // namespace miem

# Standardized Emissions Schema (SES) 1.0

## Overview

SES defines the NetCDF convention for emission input files consumed by MIEM.
Files conforming to this schema are processed without a DatasetDescriptor;
non-conforming files require a descriptor to map their layout to SES conventions.

## Dimensions

| Dimension | Meaning | Notes |
|-----------|---------|-------|
| `n_cells` | Spatial cells (host-grid-aligned, 1D) | Required |
| `time` | Time steps | Required, unlimited |

## Global Attributes

| Attribute | Type | Required | Example |
|-----------|------|----------|---------|
| `ses_version` | string | **Yes** | `"1.0"` |
| `Conventions` | string | **Yes** | `"CF-1.8"` |
| `grid_description` | string | Recommended | `"CAM-SE ne30np4"` |
| `source_inventory` | string | Recommended | `"CEDSv2024-04"` |
| `preprocessing_tool_version` | string | Recommended | `"UPTEMPO 0.1.0"` |

Legacy files using `miem_version` instead of `ses_version` are accepted.

## Time Coordinate

- Variable name: `time`
- Must have a `units` attribute in CF format: e.g., `"days since 2000-01-01"`
- Calendar attribute recommended: `calendar = "standard"`

## Emission Variables

- Naming: `emi_<species>(time, n_cells)` — e.g., `emi_NOx`, `emi_SO2`
- Required `units` attribute: `"kg m-2 s-1"`
- Optional `_FillValue` attribute (masked to 0.0 by reader)
- Compression recommendation: `deflate_level=1`

## Example (CDL)

```
netcdf example_ses {
dimensions:
    n_cells = 48602 ;
    time = UNLIMITED ;
variables:
    double time(time) ;
        time:units = "days since 2000-01-01" ;
        time:calendar = "standard" ;
    double emi_NOx(time, n_cells) ;
        emi_NOx:units = "kg m-2 s-1" ;
    double emi_SO2(time, n_cells) ;
        emi_SO2:units = "kg m-2 s-1" ;

// global attributes:
    :ses_version = "1.0" ;
    :Conventions = "CF-1.8" ;
    :source_inventory = "CEDSv2024-04" ;
    :grid_description = "CAM-SE ne30np4" ;
}
```

## Backward Compatibility

MIEM accepts legacy files that use:
- `miem_version` instead of `ses_version`
- `nCells` instead of `n_cells`
- `Time` instead of `time`

These files are detected as CES-compliant and processed identically to SES 1.0
files. New files should use SES 1.0 conventions.

